def solve(grid):
    if not grid:
        return 0
    rows = len(grid)
    visited = set()
    def dfs(r,c):
        stack = [(r,c)]
        while stack:
            i,j = stack.pop()
            if i<0 or i>=rows:
                continue
            if j<0 or j>=len(grid[i]):
                continue
            if (i,j) in visited:
                continue
            if grid[i][j] != 1:
                continue
            visited.add((i,j))
            stack.extend([(i-1,j),(i+1,j),(i,j-1),(i,j+1)])
    count=0
    for i in range(rows):
        for j in range(len(grid[i])):
            if grid[i][j]==1 and (i,j) not in visited:
                dfs(i,j)
                count+=1
    return count

