def solve(s) -> bool:
    """Return True if brackets in *s* are balanced.
    Handles strings, bytes, bytearray, and any iterable of characters/ASCII codes.
    Non‑iterable inputs are considered to contain no brackets (balanced).
    """
    # Decode bytes / bytearray to string.
    if isinstance(s, (bytes, bytearray)):
        try:
            s = s.decode()
        except Exception:
            s = ''
    # If not iterable, treat as balanced.
    try:
        iterator = iter(s)
    except TypeError:
        return True
    stack = []
    opening = set('([{')
    matching = {')': '(', ']': '[', '}': '{'}
    for ch in iterator:
        # If element is an int (e.g., iterating over bytes), convert to character.
        if isinstance(ch, int):
            try:
                ch = chr(ch)
            except Exception:
                continue
        # Only process string characters.
        if not isinstance(ch, str):
            continue
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return not stack

