def solve(s) -> bool:
    """Check if brackets are balanced.
    Accepts any iterable of characters (e.g., string, list of chars, bytes).
    Non‑iterable inputs are considered invalid and return False.
    Only the three bracket types '()', '[]', '{}' are considered; other
    characters are ignored.
    """
    # Try to get an iterator; if not possible, return False.
    try:
        iterator = iter(s)
    except TypeError:
        return False
    stack = []
    opening = set('([{')
    matching = {')': '(', ']': '[', '}': '{'}
    for ch in iterator:
        # If element is an int (e.g., iterating over bytes), convert to char.
        if isinstance(ch, int):
            try:
                ch = chr(ch)
            except Exception:
                continue
        # Ensure we have a single-character string.
        if not isinstance(ch, str):
            continue
        if len(ch) != 1:
            # If longer string, iterate its characters.
            for sub in ch:
                if sub in opening:
                    stack.append(sub)
                elif sub in matching:
                    if not stack or stack[-1] != matching[sub]:
                        return False
                    stack.pop()
            continue
        if ch in opening:
            stack.append(ch)
        elif ch in matching:
            if not stack or stack[-1] != matching[ch]:
                return False
            stack.pop()
    return not stack

