        matrix.append([1 if cell else 0 for cell in row])
    n = len(matrix)
    m = max((len(row) for row in matrix), default=0)
    visited = [[False]*len(row) for row in matrix]
    def dfs(i, j):
        stack = [(i, j)]
        while stack:
            x, y = stack.pop()
            if x < 0 or x >= n or y < 0 or y >= len(matrix[x]):
                continue
            if visited[x][y] or matrix[x][y] != 1:
                continue
            visited[x][y] = True
            stack.extend([(x-1, y), (x+1, y), (x, y-1), (x, y+1)])
