def solve(word1: str, word2: str) -> int:
    """Compute Levenshtein distance using memoization.
    Handles empty strings and works for any Unicode characters.
    """
    from functools import lru_cache
    @lru_cache(None)
    def dp(i: int, j: int) -> int:
        # distance between word1[i:] and word2[j:]
        if i == len(word1):
            return len(word2) - j
        if j == len(word2):
            return len(word1) - i
        if word1[i] == word2[j]:
            return dp(i+1, j+1)
        # try delete (i+1, j), insert (i, j+1), replace (i+1, j+1)
        return 1 + min(dp(i+1, j), dp(i, j+1), dp(i+1, j+1))
    return dp(0,0)

